import {spawn} from 'node:child_process';
import {mkdir,writeFile,appendFile} from 'node:fs/promises';import {join} from 'node:path';
import {createResumableEngineeringService,approvalHash} from '../../src/engineering-run.js';import {projectFiles} from '../../src/engineering.js';import {defaultChatOptions} from '../../src/chat-options.js';import type {Plan} from '../../src/engineering-plan.js';
const [root,action,id]=process.argv.slice(2) as [string,string,string];
const testSource=(id:string,n:number)=>`import {test} from 'node:test';import assert from 'node:assert/strict';import {value} from './${id}.mjs';test('${id}',()=>assert.equal(value,${n}));`;
const task=(id:string,n:number,dependsOn:string[])=>({id,goal:id,dependsOn,outputs:[id+'.mjs'],acceptance:[id+' = '+n],testSource:testSource(id,n)});
const plan:Plan={summary:'compose',outputs:['a.mjs','b.mjs','total.mjs'],acceptance:['total = 5'],testSource:testSource('total',5),limitations:[],tasks:[task('a',2,[]),task('b',3,['a']),task('total',5,['a','b'])]};
if(action==='create-long')plan.tasks![0]!.testSource+='await new Promise(r=>setTimeout(r,30000));';
if(action==='create-bad')plan.testSource=testSource('total',6);
const service=createResumableEngineeringService(root,process.execPath,{run:async(_spec,job)=>{if(action==='orphan'){const child=spawn(process.execPath,['-e','setTimeout(()=>{},60000)'],{detached:true,stdio:'ignore'});child.unref();await writeFile(join(root,'orphan.json'),JSON.stringify({pid:child.pid}));process.exit(17);}
await appendFile(join(root,'workers.jsonl'),JSON.stringify({id:job.id,sessionId:job.sessionId})+'\n');await writeFile(join(job.workspace,job.id+'.mjs'),job.id==='total'?"import {value as a} from './a.mjs';import {value as b} from './b.mjs';export const value=a+b;":`export const value=${job.id==='a'?2:3};`);return {status:'completed',sessionId:job.id,durationMs:1,text:'done',usage:{fixture:true}};},challenge:async c=>({checks:c.acceptance.map(criterion=>({criterion,source:`import assert from 'node:assert/strict';import {pathToFileURL} from 'node:url';const {value}=await import(pathToFileURL(process.cwd()+'/${c.outputs[0]}').href);assert.equal(value,${c.goal==='a'?2:c.goal==='b'?3:5});`})),limitations:[]}),onEvent:async(s,type)=>{if(action==='hold'&&type==='execution-started'){await writeFile(join(root,'held'),'ready');await new Promise(r=>setTimeout(r,1500));}
if(action==='cancel-settlement'&&type==='settled'&&s.delivery)void service.cancel(s.id);
if(action==='crash'&&type==='team-checkpoint'&&s.team?.tasks.a?.status==='accepted')process.exit(17);
if(action==='check-crash'&&type==='reserved:verification')process.exit(17);
if(action==='pause'&&type==='team-checkpoint'&&s.team?.tasks.a?.status==='accepted')service.requestPause();}});
if(action.startsWith('create')){const project=join(root,'project');await mkdir(project,{recursive:true});await writeFile(join(project,'baseline.test.mjs'),"import {test} from 'node:test';import assert from 'node:assert/strict';test('baseline',()=>assert.equal(1+1,2));");const result=await service.create({project,goal:'compose',plan,options:defaultChatOptions,approvedHash:approvalHash('compose',await projectFiles(project),plan),fixture:true,concurrency:1,maxCalls:action==='create-budget'?1:32,totalMs:action==='create-expired'?1:1200000});console.log(JSON.stringify(result));}else {await service.resume(id);await service.wait();console.log(JSON.stringify(await service.detail(id)));}
